using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class DockReferenceDetails {
const string D="Assets/Scenes/Oasis/SouthBeach";static DockReferenceDetails(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("DockReferenceDetails.request"))return;try{File.Delete("DockReferenceDetails.request");}catch(IOException){return;}Run();}
class Geo{public List<Vector3> p=new List<Vector3>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c){int n=p.Count;p.AddRange(new[]{a,b,c});ids.AddRange(new[]{n,n+1,n+2});}public void Box(Vector3 center,Vector3 size){var v=new Vector3[8];for(int i=0;i<8;i++)v[i]=center+Vector3.Scale(new Vector3((i&1)==0?-.5f:.5f,(i&2)==0?-.5f:.5f,(i&4)==0?-.5f:.5f),size);foreach(var face in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}}){Tri(v[face[0]],v[face[1]],v[face[2]]);Tri(v[face[0]],v[face[2]],v[face[3]]);}}
public void Pole(Vector3 a,Vector3 b,float radius,int sides=6){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var v=Vector3.Cross(axis,u);for(int k=0;k<sides;k++){float q=k*2*Mathf.PI/sides,r=(k+1)*2*Mathf.PI/sides;var o=u*Mathf.Cos(q)+v*Mathf.Sin(q);var n=u*Mathf.Cos(r)+v*Mathf.Sin(r);Tri(a+o*radius,b+o*radius,a+n*radius);Tri(a+n*radius,b+o*radius,b+n*radius);Tri(a,a+n*radius,a+o*radius);Tri(b,b+o*radius,b+n*radius);}}
public void Ring(Vector3 center,float radius,float tube){for(int j=0;j<16;j++)for(int k=0;k<4;k++){Func<int,int,Vector3> point=(s,t)=>{float a=s*Mathf.PI/8,b=t*Mathf.PI/2;return center+new Vector3(Mathf.Cos(a)*(radius+tube*Mathf.Cos(b)),Mathf.Sin(a)*(radius+tube*Mathf.Cos(b)),tube*Mathf.Sin(b));};var a0=point(j,k);var b0=point(j+1,k);var c0=point(j+1,k+1);var d0=point(j,k+1);Tri(a0,b0,c0);Tri(a0,c0,d0);}}
public Mesh Save(string path){var mesh=new Mesh{name="Mobile dock reference detail",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(p);mesh.SetTriangles(ids,0);mesh.SetUVs(0,p.Select(v=>new Vector2(v.x*.5f,v.z*.5f)).ToList());mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}}
static Material Mat(string name,Color color,bool glow=false){var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/"+name+".mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,D+"/"+name+".mat");}mat.SetColor("_BaseColor",color);mat.SetFloat("_Smoothness",.18f);mat.enableInstancing=true;if(glow){mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",new Color(.7f,.55f,.32f)*1.3f);}EditorUtility.SetDirty(mat);return mat;}
static Renderer Child(GameObject root,string name,Geo geo,Material mat,string path){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=geo.Save(path);var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;return r;}
static void Run(){try{Directory.CreateDirectory(D+"/DockDetails");var ropeMat=Mat("Shared dock rope",new Color(.51f,.43f,.28f));var metal=Mat("Shared dock metal",new Color(.18f,.21f,.22f));var orange=Mat("Shared dock safety orange",new Color(.86f,.18f,.055f));var white=Mat("Shared dock lamp globes",new Color(.9f,.87f,.75f),true);var wood=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared pier weathered wood.mat");long tris=0;
for(int index=1;index<=6;index++){string path=D+"/Docking Pier "+index+".prefab";var prefab=PrefabUtility.LoadPrefabContents(path);if(prefab.transform.Find("Reference dock details")){PrefabUtility.UnloadPrefabContents(prefab);continue;}float span=52+((index-1)%3)*7;var detail=new GameObject("Reference dock details");detail.transform.SetParent(prefab.transform,false);var timber=new Geo();var ropes=new Geo();var steel=new Geo();var safety=new Geo();var lamps=new Geo();foreach(float x in new[]{-2.15f,2.15f}){for(float z=4;z<span-6;z+=7){timber.Pole(new Vector3(x,.25f,z),new Vector3(x,1.35f,z),.10f);if(z+7<span-6){for(int tier=0;tier<2;tier++){float y=.75f+tier*.43f;var a=new Vector3(x,y,z);var mid=new Vector3(x,y-.12f,z+3.5f);var b=new Vector3(x,y,z+7);ropes.Pole(a,mid,.032f,4);ropes.Pole(mid,b,.032f,4);}}}}
for(float z=3;z<span-9;z+=9){timber.Pole(new Vector3(-1.9f,-4.7f,z),new Vector3(1.9f,-.5f,z+9),.14f,4);timber.Pole(new Vector3(1.9f,-4.7f,z),new Vector3(-1.9f,-.5f,z+9),.14f,4);}
foreach(float z in new[]{span-4,span-13,span*.45f})foreach(float x in new[]{-1.7f,1.7f}){steel.Pole(new Vector3(x,.25f,z),new Vector3(x,.65f,z),.10f);steel.Pole(new Vector3(x-.25f,.58f,z),new Vector3(x+.25f,.58f,z),.09f);steel.Box(new Vector3(x,.28f,z),new Vector3(.5f,.10f,.45f));}
foreach(float z in new[]{span*.36f,span-9}){steel.Pole(new Vector3(-1.5f,.25f,z),new Vector3(-1.5f,2.55f,z),.065f);lamps.Pole(new Vector3(-1.5f,2.52f,z),new Vector3(-1.5f,2.9f,z),.21f,8);safety.Ring(new Vector3(-2.15f,.89f,z),.36f,.09f);}
float ladderZ=span-8;foreach(float z in new[]{ladderZ-.35f,ladderZ+.35f})steel.Pole(new Vector3(2.42f,-2.4f,z),new Vector3(2.42f,.85f,z),.055f);for(float y=-2.2f;y<.8f;y+=.35f)steel.Pole(new Vector3(2.42f,y,ladderZ-.35f),new Vector3(2.42f,y,ladderZ+.35f),.04f);
var renderers=new List<Renderer>();int part=0;foreach(var entry in new[]{Tuple.Create(timber,wood,"Weathered braces and railing posts"),Tuple.Create(ropes,ropeMat,"Sagging rope rails"),Tuple.Create(steel,metal,"Mooring bollards and boarding ladder"),Tuple.Create(safety,orange,"Life rings"),Tuple.Create(lamps,white,"Dock lamp globes")}){renderers.Add(Child(detail,entry.Item3,entry.Item1,entry.Item2,D+"/DockDetails/Pier "+index+" detail "+part+++".asset"));tris+=entry.Item1.ids.Count/3;}var baseRenderers=prefab.GetComponentsInChildren<MeshRenderer>().Where(r=>!r.transform.IsChildOf(detail.transform)).Cast<Renderer>().ToArray();var lod=prefab.GetComponent<LODGroup>();if(!lod)lod=prefab.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.10f,baseRenderers.Concat(renderers).ToArray()),new LOD(.012f,baseRenderers)});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}
AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var root=scene.GetRootGameObjects().Single(g=>g.name=="South Beach Bays and Docking Piers");var first=root.transform.GetChild(2);float len=52+2*7;Vector3 target=first.TransformPoint(new Vector3(0,0,len*.65f));var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,target+first.TransformDirection(new Vector3(18,15,-19)),target,"Reference-Docking-Pier-Details"});File.WriteAllText("FinalEnvironmentRoadReview/DockReferenceDetailsReport.txt","SUCCESS six pier prefabs: diagonal foundation braces, sagging rope railing, T mooring bollards, life rings, ladders, dock globe lamps; added triangles="+tris+"; spatially batched by five shared instanced materials; two LODs omit details at distance; no extra realtime lights; deck colliders retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/DockReferenceDetailsReport.txt","FAILED "+e);Debug.LogException(e);}}
